let overlay;
export const SAMPLE_MESSAGE_VIDEO='https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4';
export function openLetterVideo(trigger){
 if(!overlay){overlay=document.createElement('dialog');overlay.className='letter-video';overlay.setAttribute('aria-label','A message from Santa');overlay.innerHTML=`<div class="letter-video-frame"><button aria-label="Close video" class="letter-video-close">×</button><video controls playsinline preload="metadata" src="${SAMPLE_MESSAGE_VIDEO}"></video><p role="status"></p></div>`;document.body.append(overlay);const close=()=>{overlay.querySelector('video').pause();overlay.close();};overlay.querySelector('button').onclick=close;overlay.addEventListener('click',e=>{if(e.target===overlay)close();});overlay.addEventListener('cancel',e=>{e.preventDefault();close();});overlay.addEventListener('keydown',e=>e.stopPropagation());overlay.addEventListener('close',()=>{overlay.querySelector('video').pause();window.dispatchEvent(new Event('resume-calendar-music'));});}
 overlay.showModal();window.dispatchEvent(new Event('pause-calendar-music'));const video=overlay.querySelector('video');video.controls=true;video.currentTime=0;overlay.querySelector('p').textContent='';video.onerror=()=>{overlay.querySelector('p').textContent='The sample video could not load. Please try again.';};video.play().catch(()=>{overlay.querySelector('p').textContent='Press Play to start the video.';});overlay.querySelector('button').focus();
}
